export function manifestFlatIndex(
  data: ResearchData,
  sectionIndex: number,
  itemIndex: number,
): number {
  let flat = 0
  for (let si = 0; si < sectionIndex; si++) {
    flat += data.sections[si]!.items.length
  }
  return flat + itemIndex
}

export function gameResearchIdForManifest(
  data: ResearchData,
  sectionIndex: number,
  itemIndex: number,
): number | null {
  const flat = manifestFlatIndex(data, sectionIndex, itemIndex)
  if (flat < 0 || flat >= GAME_MANIFEST_FLAT_TO_RESEARCH_ID.length) return null
  const id = GAME_MANIFEST_FLAT_TO_RESEARCH_ID[flat]!
  if (id < 0 || id >= GAME_RESEARCH_SLOT_COUNT) return null
  return id
}
